package org.casbin.jcasbin.log;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class LogRoleTests {

    private final ByteArrayOutputStream outContent = new ByteArrayOutputStream();
    private final PrintStream originalOut = System.out;

    private DefaultLogger logger;

    @BeforeEach
    public void setUp() {
        System.setOut(new PrintStream(outContent));
        logger = new DefaultLogger();
    }

    @AfterEach
    public void restoreStreams() {
        System.setOut(originalOut);
    }

    @Test
    public void testLogRoleWithEnabledLogger() {
        logger.enable();
        String[] roles = {"admin", "user", "guest"};
        logger.logRole(roles);

        String expectedOutput = "Role: admin" + System.lineSeparator() +
                                "Role: user" + System.lineSeparator() +
                                "Role: guest" + System.lineSeparator();
        assertEquals(expectedOutput, outContent.toString());
    }

    @Test
    public void testLogRoleWithDisabledLogger() {
        logger.disable();
        String[] roles = {"admin", "user"};
        logger.logRole(roles);

        assertEquals("", outContent.toString());
    }

    @Test
    public void testLogRoleWithEmptyArray() {
        logger.enable();
        String[] roles = {};
        logger.logRole(roles);

        assertEquals("", outContent.toString());
    }

    @Test
    public void testLogRoleWithSingleRole() {
        logger.enable();
        String[] roles = {"administrator"};
        logger.logRole(roles);

        String expectedOutput = "Role: administrator" + System.lineSeparator();
        assertEquals(expectedOutput, outContent.toString());
    }
}

