import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.*;

class StartAutoLoadPolicyTests {

    private SyncedEnforcer enforcer;
    private File modelFile;
    private File policyFile;

    @TempDir
    Path tempDir;

    @BeforeEach
    void setUp() throws IOException {
        // Create a simple model file
        modelFile = new File(tempDir.toFile(), "model.conf");
        try (FileWriter writer = new FileWriter(modelFile)) {
            writer.write("[request_definition]\n" +
                    "r = sub, obj, act\n" +
                    "\n" +
                    "[policy_definition]\n" +
                    "p = sub, obj, act\n" +
                    "\n" +
                    "[policy_effect]\n" +
                    "e = some(where (p.eft == allow))\n" +
                    "\n" +
                    "[matchers]\n" +
                    "m = r.sub == p.sub && r.obj == p.obj && r.act == p.act");
        }

        // Create a simple policy file
        policyFile = new File(tempDir.toFile(), "policy.csv");
        try (FileWriter writer = new FileWriter(policyFile)) {
            writer.write("p, alice, data1, read");
        }

        enforcer = new SyncedEnforcer(modelFile.getAbsolutePath(), policyFile.getAbsolutePath());
    }

    @AfterEach
    void tearDown() {
        if (enforcer != null) {
            enforcer.stopAutoLoadPolicy();
        }
    }

    @Test
    void testStartAutoLoadPolicy_Success() throws InterruptedException {
        // Check if auto-load is currently running (should be false initially)
        assertFalse(isAutoLoadRunning());

        enforcer.startAutoLoadPolicy(100);

        // Wait a moment to ensure the thread starts
        Thread.sleep(200);

        // Check if auto-load is running
        assertTrue(isAutoLoadRunning());
    }

    @Test
    void testStartAutoLoadPolicy_AlreadyRunning() {
        enforcer.startAutoLoadPolicy(100);

        // Try to start it again. According to invariants, only one should run.
        // The implementation should check atomic flag and not start a new thread.
        // We capture the thread count before and after to ensure it doesn't increase
        // (or simply that it doesn't crash).

        assertDoesNotThrow(() -> enforcer.startAutoLoadPolicy(100));

        // Wait to verify state consistency if needed, 
        // but primarily we verify it handles the concurrent start gracefully.
    }

    @Test
    void testStartAutoLoadPolicy_LoadsPolicy() throws InterruptedException, IOException {
        enforcer.startAutoLoadPolicy(200);

        // Verify initial policy exists
        assertTrue(enforcer.enforce("alice", "data1", "read"));

        // Modify the external policy file
        try (FileWriter writer = new FileWriter(policyFile, true)) {
            writer.write("\np, bob, data2, write");
        }

        // Wait for the auto-load to pick up the change (interval is 200ms)
        Thread.sleep(500);

        // Verify new policy is loaded
        assertTrue(enforcer.enforce("bob", "data2", "write"));
    }

    @Test
    void testStartAutoLoadPolicy_ThreadInterruption() throws InterruptedException {
        AtomicBoolean wasInterrupted = new AtomicBoolean(false);

        enforcer.startAutoLoadPolicy(50);

        // Stop the auto load policy, which should interrupt the thread
        Thread.sleep(100); 
        enforcer.stopAutoLoadPolicy();

        // Verify that the flag is reset
        Thread.sleep(100);
        assertFalse(isAutoLoadRunning());
    }

    @Test
    void testStartAutoLoadPolicy_ConcurrencyStress() throws InterruptedException {
        int threadCount = 10;
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            threads[i] = new Thread(() -> enforcer.startAutoLoadPolicy(100));
        }

        // Start all threads roughly at the same time
        for (Thread t : threads) {
            t.start();
        }

        // Wait for all to complete
        for (Thread t : threads) {
            t.join();
        }

        // Wait for the internal thread to spin up
        Thread.sleep(200);

        // Despite multiple calls, the internal running flag should indicate active
        assertTrue(isAutoLoadRunning());
    }

    // Helper method to access private field 'autoLoadRunning' via reflection
    private boolean isAutoLoadRunning() {
        try {
            java.lang.reflect.Field field = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
            field.setAccessible(true);
            if (field.getType() == AtomicInteger.class) {
                AtomicInteger val = (AtomicInteger) field.get(enforcer);
                return val.get() == 1;
            } else if (field.getType() == Boolean.class || field.getType() == boolean.class) {
                 return field.getBoolean(enforcer);
            }
            return false;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }
}

