import java.util.List;
import java.util.function.BooleanSupplier;

import static org.junit.jupiter.api.Assertions.*;

class RemoveFilteredPolicySelfTests {

    private static final String MODEL_PATH = "src/test/resources/examples/rbac_model.conf";
    private static final String POLICY_PATH = "src/test/resources/examples/rbac_policy.csv";
    private static final String TEMP_POLICY_PATH = "src/test/resources/examples/rbac_policy_temp.csv";
    private DistributedEnforcer enforcer;
    private Model model;

    @BeforeEach
    void setUp() throws IOException {
        // Create a temporary file for testing adapter persistence to avoid modifying the original test file
        Path source = Paths.get(POLICY_PATH);
        Path target = Paths.get(TEMP_POLICY_PATH);
        if (Files.exists(target)) {
            Files.delete(target);
        }
        Files.copy(source, target);
    }

    @AfterEach
    void tearDown() throws IOException {
        // Clean up the temporary file
        Path target = Paths.get(TEMP_POLICY_PATH);
        if (Files.exists(target)) {
            Files.delete(target);
        }
    }

    private void initEnforcer(boolean useFileAdapter) {
        if (useFileAdapter) {
            enforcer = new DistributedEnforcer(MODEL_PATH, TEMP_POLICY_PATH);
        } else {
            // For testing in-memory operations without persistence
            model = new Model();
            model.loadModelFromText(MODEL_PATH_CONF);
            Adapter adapter = new FileAdapter(POLICY_PATH);
            adapter.loadPolicy(model);
            // Disconnect adapter to test pure in-memory removal via Enforcer logic if needed, 
            // but removeFilteredPolicySelf relies on super.removeFilteredPolicy which calls adapter.
            // For true in-memory tests, we would mock the adapter.
        }
    }

    private static final String MODEL_PATH_CONF = 
            "[request_definition]\n" +
            "r = sub, obj, act\n" +
            "\n" +
            "[policy_definition]\n" +
            "p = sub, obj, act\n" +
            "\n" +
            "[role_definition]\n" +
            "g = _, _\n" +
            "\n" +
            "[policy_effect]\n" +
            "e = some(where (p.eft == allow))\n" +
            "\n" +
            "[matchers]\n" +
            "m = g(r.sub, p.sub) && r.obj == p.obj && r.act == p.act";

    @Test
    void testRemoveFilteredPolicySelf_PSection_PersistTrue() {
        initEnforcer(true);

        // Initial check
        assertTrue(enforcer.hasPolicy("alice", "data1", "read"));

        // Remove policy where sub is "alice"
        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> true, "p", "p", 0, "alice");

        assertNotNull(removed);
        assertEquals(1, removed.size());
        assertEquals(Arrays.asList("alice", "data1", "read"), removed.get(0));

        // Verify it is removed from memory model
        assertFalse(enforcer.hasPolicy("alice", "data1", "read"));

        // Since we used FileAdapter and persisted, verify it is removed from file for subsequent loads
        DistributedEnforcer newEnforcer = new DistributedEnforcer(MODEL_PATH, TEMP_POLICY_PATH);
        assertFalse(newEnforcer.hasPolicy("alice", "data1", "read"));
    }

    @Test
    void testRemoveFilteredPolicySelf_PSection_PersistFalse() {
        initEnforcer(true);

        // Initial check
        assertTrue(enforcer.hasPolicy("bob", "data2", "write"));

        // Remove policy where sub is "bob", but do not persist
        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> false, "p", "p", 0, "bob");

        assertNotNull(removed);
        assertEquals(1, removed.size());
        assertEquals(Arrays.asList("bob", "data2", "write"), removed.get(0));

        // Verify it is removed from memory model
        assertFalse(enforcer.hasPolicy("bob", "data2", "write"));

        // Since we did not persist, verify it is STILL in the file for subsequent loads
        DistributedEnforcer newEnforcer = new DistributedEnforcer(MODEL_PATH, TEMP_POLICY_PATH);
        assertTrue(newEnforcer.hasPolicy("bob", "data2", "write"));
    }

    @Test
    void testRemoveFilteredPolicySelf_GSection_PersistTrue() {
        initEnforcer(true);

        // Initial check: alice has role data_group_admin
        assertTrue(enforcer.hasRoleForUser("alice", "data_group_admin"));

        // Remove role inheritance where sub is "alice"
        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> true, "g", "g", 0, "alice");

        assertNotNull(removed);
        assertEquals(1, removed.size());
        assertEquals(Arrays.asList("alice", "data_group_admin"), removed.get(0));

        // Verify it is removed from memory model
        assertFalse(enforcer.hasRoleForUser("alice", "data_group_admin"));

        // Verify persistence
        DistributedEnforcer newEnforcer = new DistributedEnforcer(MODEL_PATH, TEMP_POLICY_PATH);
        assertFalse(newEnforcer.hasRoleForUser("alice", "data_group_admin"));
    }

    @Test
    void testRemoveFilteredPolicySelf_GSection_PersistFalse() {
        initEnforcer(true);

        // Initial check
        assertTrue(enforcer.hasRoleForUser("alice", "data_group_admin"));

        // Remove but do not persist
        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> false, "g", "g", 0, "alice");

        assertNotNull(removed);
        assertEquals(1, removed.size());

        // Verify memory removal
        assertFalse(enforcer.hasRoleForUser("alice", "data_group_admin"));

        // Verify file persistence did not happen
        DistributedEnforcer newEnforcer = new DistributedEnforcer(MODEL_PATH, TEMP_POLICY_PATH);
        assertTrue(newEnforcer.hasRoleForUser("alice", "data_group_admin"));
    }

    @Test
    void testRemoveFilteredPolicySelf_NoMatchFound() {
        initEnforcer(true);

        // Try to remove a policy that doesn't exist
        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> true, "p", "p", 0, "nonexistent");

        assertNotNull(removed);
        assertTrue(removed.isEmpty());

        // Ensure existing policies are intact
        assertTrue(enforcer.hasPolicy("alice", "data1", "read"));
    }

    @Test
    void testRemoveFilteredPolicySelf_UnsupportedOperationException() {
        initEnforcer(true);

        // Use an adapter that does not implement removeFilteredPolicy
        Adapter dummyAdapter = new Adapter() {
            @Override
            public void loadPolicy(Model model) {
                // No-op
            }

            @Override
            public void savePolicy(Model model) {
                // No-op
            }

            @Override
            public void addPolicy(String sec, String ptype, List<String> rule) {
                // No-op
            }

            @Override
            public void removePolicy(String sec, String ptype, List<String> rule) {
                // No-op
            }

            @Override
            public void removeFilteredPolicy(String sec, String ptype, int fieldIndex, String... fieldValues) {
                throw new UnsupportedOperationException("Not supported");
            }
        };

        enforcer.setAdapter(dummyAdapter);
        // Reload policies into model so enforcer state is valid, but adapter is dumb
        enforcer.getAdapter().loadPolicy(enforcer.getModel());
        enforcer.loadPolicy(); // syncs model and internal enforcer state

        // Attempt to remove
        // Based on function spec: returns null if exception occurs during persistence
        List<List<String>> result = enforcer.removeFilteredPolicySelf(() -> true, "p", "p", 0, "alice");

        assertNull(result);
    }

    @Test
    void testRemoveFilteredPolicySelf_MultipleFieldValues() {
        initEnforcer(true);

        // Add a temporary policy to ensure we have multiple for testing filtering
        enforcer.addPolicy("alice", "data3", "write");
        assertTrue(enforcer.hasPolicy("alice", "data3", "write"));

        // Remove policies where sub="alice" AND obj="data1" (fieldIndex=0, fieldValues="alice")
        // Note: The standard removeFilteredPolicy in jCasbin usually filters based on fieldIndex and subsequent fields.
        // If fieldIndex is 0 and we pass "alice", it matches ("alice", ...). 
        // Here we test removing "alice", "data1", "read". 
        // In rbac_policy.csv, alice only has one rule: data1, read.
        // Let's assume standard behavior: removeFilteredPolicy(0, "alice") removes all rules starting with alice.

        List<List<String>> removed = enforcer.removeFilteredPolicySelf(() -> true, "p", "p", 0, "alice");

        assertNotNull(removed);
        // Should remove both ("alice", "data1", "read") and ("alice", "data3", "write")
        assertEquals(2, removed.size());
    }
}

