import static org.junit.jupiter.api.Assertions.*;

public class RemoveMatchesTests {

    private Role roleA;
    private Role roleB;
    private Role roleC;

    @BeforeEach
    public void setUp() throws Exception {
        roleA = createRole("roleA");
        roleB = createRole("roleB");
        roleC = createRole("roleC");
    }

    /**
     * Helper method to create a Role instance using reflection, as the constructor is protected.
     */
    private Role createRole(String name) throws Exception {
        java.lang.reflect.Constructor<Role> constructor = Role.class.getDeclaredConstructor(String.class);
        constructor.setAccessible(true);
        return constructor.newInstance(name);
    }

    /**
     * Helper method to get the 'matched' map from a Role instance via reflection.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Role> getMatchedMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matched");
        field.setAccessible(true);
        return (Map<String, Role>) field.get(role);
    }

    /**
     * Helper method to get the 'matchedBy' map from a Role instance via reflection.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Role> getMatchedByMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matchedBy");
        field.setAccessible(true);
        return (Map<String, Role>) field.get(role);
    }

    @Test
    public void testRemoveMatchesWhenMatchedByIsEmpty() throws Exception {
        // Arrange
        Map<String, Role> matchedBy = getMatchedByMap(roleA);
        assertTrue(matchedBy.isEmpty(), "Initial state should have no matches");

        Map<String, Role> matched = getMatchedMap(roleA);

        // Act
        roleA.removeMatches();

        // Assert
        assertTrue(matchedBy.isEmpty(), "matchedBy should still be empty");
        assertTrue(matched.isEmpty(), "matched should still be empty");
    }

    @Test
    public void testRemoveMatchesClearsMatchedByAndRemovesNameFromOthers() throws Exception {
        // Arrange: Simulate roleA being matched by roleB and roleC
        Map<String, Role> roleBMatched = getMatchedMap(roleB);
        roleBMatched.put(roleA.name, roleA);

        Map<String, Role> roleCMatched = getMatchedMap(roleC);
        roleCMatched.put(roleA.name, roleA);

        Map<String, Role> roleAMatchedBy = getMatchedByMap(roleA);
        roleAMatchedBy.put(roleB.name, roleB);
        roleAMatchedBy.put(roleC.name, roleC);

        assertEquals(2, roleAMatchedBy.size());
        assertTrue(roleBMatched.containsKey(roleA.name));
        assertTrue(roleCMatched.containsKey(roleA.name));

        // Act
        roleA.removeMatches();

        // Assert: roleA's matchedBy map should be empty
        assertTrue(roleAMatchedBy.isEmpty(), "roleA's matchedBy map should be cleared");

        // Assert: roleB's matched map should no longer contain roleA
        assertFalse(roleBMatched.containsKey(roleA.name), "roleB's matched map should not contain roleA");

        // Assert: roleC's matched map should no longer contain roleA
        assertFalse(roleCMatched.containsKey(roleA.name), "roleC's matched map should not contain roleA");
    }

    @Test
    public void testRemoveMatchesDoesNotClearSelfMatchedMap() throws Exception {
        // Arrange: roleA matched by roleB
        Map<String, Role> roleBMatched = getMatchedMap(roleB);
        roleBMatched.put(roleA.name, roleA);

        Map<String, Role> roleAMatchedBy = getMatchedByMap(roleA);
        roleAMatchedBy.put(roleB.name, roleB);

        // Pre-populate roleA's own matched map with unrelated data to ensure it isn't cleared by the logic
        // (Logic only clears 'matchedBy' of self, and 'matched' of others)
        Map<String, Role> roleAMatched = getMatchedMap(roleA);
        roleAMatched.put("some_other_role", roleB); 

        // Act
        roleA.removeMatches();

        // Assert: roleA's own matched map should remain untouched
        assertTrue(roleAMatched.containsKey("some_other_role"), 
            "removeMatches should not clear the current instance's own matched map");

        // Verify side effects
        assertTrue(roleAMatchedBy.isEmpty());
        assertFalse(roleBMatched.containsKey(roleA.name));
    }

    @Test
    public void testRemoveMatchesIdempotency() throws Exception {
        // Arrange
        Map<String, Role> roleBMatched = getMatchedMap(roleB);
        roleBMatched.put(roleA.name, roleA);

        Map<String, Role> roleAMatchedBy = getMatchedByMap(roleA);
        roleAMatchedBy.put(roleB.name, roleB);

        // Act
        roleA.removeMatches();

        // Assert state after first call
        assertTrue(roleAMatchedBy.isEmpty());
        assertFalse(roleBMatched.containsKey(roleA.name));

        // Act again
        roleA.removeMatches();

        // Assert state remains the same (no exceptions thrown)
        assertTrue(roleAMatchedBy.isEmpty());
        assertFalse(roleBMatched.containsKey(roleA.name));
