    @Test
    public void testConcurrentEnforceWithCache() throws InterruptedException {
        CachedEnforcer enforcer = new CachedEnforcer(MODEL_PATH, POLICY_PATH);
        enforcer.enableCache(true);
        int threadCount = 10;
        ExecutorService service = Executors.newFixedThreadPool(threadCount);
        CountDownLatch latch = new CountDownLatch(threadCount);
        AtomicInteger passCount = new AtomicInteger(0);

        for (int i = 0; i < threadCount; i++) {
            service.submit(() -> {
                try {
                    if (enforcer.enforce("alice", "data1", "read")) {
                        passCount.incrementAndGet();
                    }
                } finally {
                    latch.countDown();
                }
            });
        }

        latch.await();
        service.shutdown();

        // All threads should get true (either from computation or cache)
        assertEquals(threadCount, passCount.get());
    }
